-- ===================================================================================
-- Reconciled with the live database (audit, Oct 2026). These five functions were changed
-- live by migrations whose files never reached this repo, so the definitions above them in
-- this file were stale (is_inkroot_admin above still let an unauthenticated caller through).
-- CREATE OR REPLACE keeps the grants set earlier in this file. Definitions are verbatim
-- pg_get_functiondef() output from live.
-- ===================================================================================

create or replace function is_inkroot_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce(auth.role(), '') = 'service_role'
    or exists (
      select 1 from profiles where id = auth.uid() and is_platform_admin
    );
$function$;

create or replace function guild_event_entry_count(p_event_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when exists (
      select 1 from guild_events
      where id = p_event_id
        and approval_status in ('published', 'active', 'completed')
    )
    then (
      select count(*)::integer from guild_event_entries
      where event_id = p_event_id
        and (status = 'success' or (status = 'pending' and created_at > now() - interval '30 minutes'))
    )
    else null
  end;
$function$;

create or replace function guild_treasury_role(p_guild_id uuid, p_user_id uuid DEFAULT auth.uid())
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user_id is distinct from auth.uid()
     and not is_guild_member(p_guild_id)
     and not is_inkroot_admin() then
    raise exception 'Not authorized to view this guild role.';
  end if;

  return case
    when exists (
      select 1 from player_guilds g
      where g.id = p_guild_id
        and (
          (not g.is_founder_guild and g.owner_id = p_user_id)
          or (g.is_founder_guild and exists (
            select 1 from profiles p where p.id = p_user_id and p.is_founder_guild_treasurer
          ))
        )
    ) then 'leader'
    else (select m.role from player_guild_members m where m.guild_id = p_guild_id and m.user_id = p_user_id)
  end;
end;
$function$;

create or replace function create_guild_event_draft(p_guild_id uuid, p_title text, p_description text DEFAULT NULL::text, p_rules text DEFAULT NULL::text, p_event_type text DEFAULT 'other'::text, p_entry_fee_kobo bigint DEFAULT NULL::bigint, p_participant_limit integer DEFAULT NULL::integer, p_prize_structure jsonb DEFAULT '[]'::jsonb, p_guild_share_bps integer DEFAULT 0, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_organizer_id uuid DEFAULT NULL::uuid, p_cover_image_url text DEFAULT NULL::text)
 RETURNS guild_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row guild_events;
begin
  perform guild_officer_gate(p_guild_id, 'Only the guild owner can host a guild event.');
  if p_title is null or length(trim(p_title)) = 0 then
    raise exception 'Give the event a title.';
  end if;
  if p_entry_fee_kobo is null or p_entry_fee_kobo <= 0 then
    raise exception 'A guild-hosted event needs a positive entry fee.';
  end if;
  if p_organizer_id is not null and not exists (
    select 1 from player_guild_members m where m.guild_id = p_guild_id and m.user_id = p_organizer_id
  ) then
    raise exception 'The organizer must be a member of this guild.';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date <= p_start_date then
    raise exception 'End date must be after the start date.';
  end if;

  insert into guild_events (
    guild_id, host, title, description, rules, event_type, entry_fee_kobo, participant_limit,
    prize_structure, guild_share_bps, start_date, end_date, organizer_id, cover_image_url,
    created_by, approval_status, status
  ) values (
    p_guild_id, 'guild', trim(p_title), nullif(trim(coalesce(p_description, '')), ''),
    nullif(trim(coalesce(p_rules, '')), ''), coalesce(p_event_type, 'other'),
    p_entry_fee_kobo, p_participant_limit, coalesce(p_prize_structure, '[]'::jsonb),
    coalesce(p_guild_share_bps, 0), p_start_date, p_end_date, p_organizer_id, p_cover_image_url,
    auth.uid(), 'draft', 'closed'
  ) returning * into v_row;
  return v_row;
end;
$function$;

create or replace function update_guild_event_draft(p_guild_id uuid, p_event_id uuid, p_title text, p_description text DEFAULT NULL::text, p_rules text DEFAULT NULL::text, p_event_type text DEFAULT 'other'::text, p_entry_fee_kobo bigint DEFAULT NULL::bigint, p_participant_limit integer DEFAULT NULL::integer, p_prize_structure jsonb DEFAULT '[]'::jsonb, p_guild_share_bps integer DEFAULT 0, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_organizer_id uuid DEFAULT NULL::uuid, p_cover_image_url text DEFAULT NULL::text)
 RETURNS guild_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_event guild_events%rowtype;
begin
  perform guild_officer_gate(p_guild_id, 'Only the guild owner can edit this event.');
  select * into v_event from guild_events where id = p_event_id and guild_id = p_guild_id;
  if not found then
    raise exception 'Guild event not found.';
  end if;
  if v_event.approval_status not in ('draft', 'rejected') then
    raise exception 'Only a draft or rejected event can be edited.';
  end if;
  if p_title is null or length(trim(p_title)) = 0 then
    raise exception 'Give the event a title.';
  end if;
  if p_entry_fee_kobo is null or p_entry_fee_kobo <= 0 then
    raise exception 'A guild-hosted event needs a positive entry fee.';
  end if;
  if p_organizer_id is not null and not exists (
    select 1 from player_guild_members m where m.guild_id = p_guild_id and m.user_id = p_organizer_id
  ) then
    raise exception 'The organizer must be a member of this guild.';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date <= p_start_date then
    raise exception 'End date must be after the start date.';
  end if;

  update guild_events set
    title = trim(p_title),
    description = nullif(trim(coalesce(p_description, '')), ''),
    rules = nullif(trim(coalesce(p_rules, '')), ''),
    event_type = coalesce(p_event_type, 'other'),
    entry_fee_kobo = p_entry_fee_kobo,
    participant_limit = p_participant_limit,
    prize_structure = coalesce(p_prize_structure, '[]'::jsonb),
    guild_share_bps = coalesce(p_guild_share_bps, 0),
    start_date = p_start_date,
    end_date = p_end_date,
    organizer_id = p_organizer_id,
    cover_image_url = p_cover_image_url,
    approval_status = 'draft',
    rejection_reason = null,
    reviewed_by = null,
    reviewed_at = null,
    submitted_at = null
  where id = p_event_id
  returning * into v_event;
  return v_event;
end;
$function$;
